100, float a[n], float b[n], float c[n], int foo(int), void bar(),
以下哪项程序优化编译器总是可以进行？
float tmp;
for(i = 0; i < n; ++i) {  for(i = 0; i < n; ++i) {
A    a[i] += b[i];    tmp = b[i] + c[i];
  a[i] += c[i];    a[i] += tmp;
}  }
int tmp;
B  *p += *q;  tmp = *q + *r;
*p += *r;  *p += tmp;
